<?php require 'app/init.php';require 'app/view.php';$u=me();if($_SERVER['REQUEST_METHOD']==='POST'){$u=require_user();verify();$nombre=trim($_POST['nombre']??'');if(mb_strlen($nombre)>=3&&mb_strlen($nombre)<=150){$s=db()->prepare('INSERT INTO clubes(creador_id,nombre,descripcion) VALUES(?,?,?)');$s->execute([$u['id'],$nombre,trim($_POST['descripcion']??'')]);$id=db()->lastInsertId();db()->prepare("INSERT INTO miembros_club(club_id,usuario_id,rol) VALUES(?,?,'admin')")->execute([$id,$u['id']]);go('club.php?id='.$id);}}top('Clubes');?><div class="layout"><?php sidebar();?><main><h1>Clubes de lectura</h1><?php if($u):?><div class="card"><h2>Crear un club</h2><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><p><input class="field" name="nombre" maxlength="150" required placeholder="Nombre del club"></p><p><textarea name="descripcion" placeholder="¿De qué trata tu club?"></textarea></p><button>Crear club</button></form></div><?php endif;?><?php foreach(db()->query('SELECT c.*,(SELECT COUNT(*) FROM miembros_club m WHERE m.club_id=c.id) miembros FROM clubes c ORDER BY c.id DESC') as $c):?><div class="card"><h2><a href="club.php?id=<?=$c['id']?>"><?=e($c['nombre'])?></a></h2><p><?=e($c['descripcion'])?></p><span class="muted"><?=$c['miembros']?> miembros</span><p><a class="btn" href="club.php?id=<?=$c['id']?>">Ver club →</a></p></div><?php endforeach;?></main><?php rightbar();?></div><?php bottom();?>